using System; using System.Data; using System.Data.SqlClient; using System.Web.Script.Services; using System.Web.Services;
namespace WamoApp { public partial class RequestPage : BasePage { [WebMethod][ScriptMethod(ResponseFormat = ResponseFormat.Json)] public static object SubmitRequest(string serviceName, string address, string preferredDate, string preferredTime, string description, string photoUrl, string latitude, string longitude) { SecurityHelper.ValidateCsrfOrThrow(); var nextNumber = Convert.ToInt32(DbHelper.ExecuteScalar("SELECT ISNULL(MAX(RequestID), 0) + 1 FROM CollectionRequests", CommandType.Text)); var requestNumber = string.Format("REQ-{0}-{1}", DateTime.UtcNow.Year, nextNumber.ToString("D6")); DbHelper.ExecuteNonQuery(@"INSERT INTO CollectionRequests (RequestNumber, CustomerID, ServiceName, AddressLine, PreferredDate, PreferredTime, Description, PhotoUrl, Latitude, Longitude, Status, CreatedDate) VALUES (@RequestNumber,@CustomerID,@ServiceName,@AddressLine,@PreferredDate,@PreferredTime,@Description,@PhotoUrl,@Latitude,@Longitude,'Pending',GETUTCDATE())", CommandType.Text, new SqlParameter("@RequestNumber", requestNumber), new SqlParameter("@CustomerID", (object)SessionManager.GetCurrentUserIdOrNull() ?? DBNull.Value), new SqlParameter("@ServiceName", serviceName ?? string.Empty), new SqlParameter("@AddressLine", address ?? string.Empty), new SqlParameter("@PreferredDate", DateTime.Parse(preferredDate)), new SqlParameter("@PreferredTime", (object)preferredTime ?? DBNull.Value), new SqlParameter("@Description", (object)description ?? DBNull.Value), new SqlParameter("@PhotoUrl", (object)photoUrl ?? DBNull.Value), new SqlParameter("@Latitude", (object)latitude ?? DBNull.Value), new SqlParameter("@Longitude", (object)longitude ?? DBNull.Value)); return new { success = true, requestNumber = requestNumber, message = "Collection request submitted successfully." }; } } }
